he:{type:3,description:"Cache static image responses (png, jpg, webp) in memory to cut redundant fetches. Bounded by entry count and TTL.",default:!1},networkCacheMinutes:{type:5,description:"How long, in minutes, the network cache keeps entries before evicting them.",markers:[1,5,10,15,30,60],default:5,stickToMarkers:!1,restartNeeded:!0},networkCacheMaxEntries:{type:5,description:"Hard cap on cached image entries. Oldest entries are evicted first when exceeded.",markers:[50,100,200,500,1e3],default:200,stickToMarkers:!1,restartNeeded:!0},forceLowImageQuality:{type:3,description:"Rewrite Discord CDN image URLs to request smaller sizes. Saves bandwidth and decode cost.",default:!1},pauseOffscreenMedia:{type:3,description:"Auto-pause videos and animated content that scroll out of view.",default:!1},memoryManagement:{type:3,description:"Periodically check JS heap pressure and trim caches when usage is high. Requires Chromium performance.memory.",default:!1},memoryCheckSeconds:{type:5,description:"Seconds between memory pressure checks.",markers:[10,30,60,120,300],default:30,stickToMarkers:!1,restartNeeded:!0},optimizeTooltips:{type:3,description:"Skip the unnecessary flushSync inside Discord's tooltip module. Smoother tooltip transitions.",default:!1,restartNeeded:!0},optimizeEmojiCache:{type:3,description:"Cache repeat emoji-pack getter calls to avoid re-walking emoji lists on every render.",default:!1,restartNeeded:!0},killLoadingSpinner:{type:3,description:"Strip the app loading spinner. It's pretty but it has measurable cost.",default:!1},killConfettiCanvas:{type:3,description:"Remove the SpriteCanvas used for confetti, particles and similar visual effects.",default:!1},killGatewayAnalytics:{type:3,description:"Drop the analytics flush block that JSON.stringifies the gateway READY payload.",default:!1},virtualizeMessages:{type:3,description:"Apply light paint containment to messages. Off by default because Discord's virtualized chat can mis-measure contained rows after updates.",default:!1},optimizeTextRendering:{type:3,description:"Apply optimizeSpeed text-rendering on message content. Disabling kerning/ligatures changes line breaks, which changes message heights and can trigger scroll re-anchoring \u2014 off by default.",default:!1},killBackdropBlur:{type:3,description:"Strip backdrop-filter blur effects (popouts, modals, overlays). Massive GPU win on integrated graphics.",default:!1},forcePassiveListeners:{type:3,description:"Force wheel, touchstart, touchmove and mousewheel listeners to passive mode. Reduces scroll input lag.",default:!1},suppressConsoleSpam:{type:3,description:"Suppress Discord's noisy console.log/debug output. Console.error and console.warn still pass through.",default:!1},freezeGifsUntilHover:{type:3,description:"Freeze animated GIFs using canvas capture (shows first frame, plays on hover). More precise but uses per-image canvas overhead.",default:!1},gifFreezeMethod:{type:4,description:"GIF freeze method. Canvas captures first frame, CSS hides until hover (more efficient but shows blank space before hover).",options:[{label:"Canvas (first frame preview)",value:"canvas",default:!0},{label:"CSS content-visibility (more efficient)",value:"css"}],disabled:()=>!It.store.freezeGifsUntilHover},throttleResizeObservers:{type:3,description:"Coalesce ResizeObserver callbacks via requestAnimationFrame. Can interfere with Discord's virtualized chat measurement after client updates, so it is off by default.",default:!1,restartNeeded:!0},reduceMotion:{type:3,description:"Apply prefers-reduced-motion globally. Disables transitions and CSS animations.",default:!1},killWillChange:{type:3,description:"Strip will-change hints Discord scatters around. Reduces GPU memory, but may hurt scroll smoothness on newer Discord builds.",default:!1},lazyEmbedImages:{type:3,description:"Use async image decoding and only lazy-load non-chat images so virtualized message rows do not resize late while scrolling.",default:!1},disableTypin